PV_MACROS = {"PREFIX": "PLC:TST:"}


@pytest.fixture(scope="module", params=(KFE_GMD_PROJECT, LFE_MOTION_PROJECT))
def project_path(request):
    return request.param


@pytest.fixture(scope="module")
def project(project_path):
    return parser.parse(project_path)


@pytest.fixture(scope="module")
def terminals(project):
    return ethercat.get_ethercat_terminals(project)


def test_project_ethercat_terminals(project, terminals):
    stateful_boxes = [
        box
        for box in project.root.find(parser.Box)
        if any(
            section.attributes.get("SlaveType") is not None
            for section in getattr(box, "EtherCAT", ())
        )
    ]
    assert terminals
    assert len({terminal.port for terminal in terminals}) == len(terminals)
    assert len({terminal.pv_component for terminal in terminals}) == len(terminals)
    assert all(
        terminal.name and terminal.port > ethercat.ADS_ECAT_SLAVE_PORT_BASE
        for terminal in terminals
    )
    assert {terminal.name: terminal.port for terminal in terminals} == {
        box.name: ethercat.ADS_ECAT_SLAVE_PORT_BASE + index
        for index, box in enumerate(stateful_boxes, start=1)
    }
    assert list(project.find(parser.Box))


def test_passive_ethercat_boxes_are_ignored(project, terminals):
    terminal_names = {terminal.name for terminal in terminals}
    passive_names = {
        box.name
        for box in project.root.find(parser.Box)
        if getattr(box, "EtherCAT", ())
        and not any(
            section.attributes.get("SlaveType") is not None
            or section.attributes.get("PdiType") is not None
            for section in box.EtherCAT
        )
    }

    assert any("EL9011" in name for name in passive_names)
    assert passive_names.isdisjoint(terminal_names)
    assert any(
        box.name not in terminal_names
        for box in project.root.find(parser.Box)
        if any(
            section.attributes.get("PdiType") is not None
            and section.attributes.get("SlaveType") is None
            for section in getattr(box, "EtherCAT", ())
        )
    )


def test_manual_ads_ports_reserve_addresses_before_auto_assignment():
    terminals = ethercat._assign_ethercat_ports(
        [
            ("Auto before fixed port", None),
            ("Fixed port", 1001),
            ("Fixed port 2", 1013),
            ("Auto after fixed ports", None),
        ]
    )

    assert [(terminal.name, terminal.port) for terminal in terminals] == [
        ("Auto before fixed port", 1002),
        ("Fixed port", 1001),
        ("Fixed port 2", 1013),
        ("Auto after fixed ports", 1014),
    ]


def test_fixed_ads_port_parses_decimal_and_hex_metadata():
    decimal_section = SimpleNamespace(
        attributes={"EtherCatAddrFixed": "true", "EtherCatAddr": "1013"}
    )
    hexadecimal_section = SimpleNamespace(
        attributes={"EtherCatAddrFixed": "true", "EtherCatAddr": "#x03f6"}
    )
    automatic_section = SimpleNamespace(attributes={"EtherCatAddrFixed": "false"})

    assert ethercat._fixed_ethercat_port("Fixed decimal", [decimal_section]) == 1013
    assert (
        ethercat._fixed_ethercat_port("Fixed hexadecimal", [hexadecimal_section])
        == 1014
    )
    assert ethercat._fixed_ethercat_port("Automatic", [automatic_section]) is None


def test_duplicate_fixed_ads_ports_are_rejected():
    with pytest.raises(ValueError, match="Duplicate EtherCAT ADS port 1013"):
        ethercat._assign_ethercat_ports(
            [("Terminal A", 1013), ("Terminal B", 1013)]
        )


def test_render_ethercat_database(terminals):
    terminal = terminals[0]
    database = ethercat.render_ethercat_database([terminal], PV_MACROS)
    base = terminal.pv_base

    expected_pvs = [
        f"$(PREFIX)ECAT:{terminal.port}:{suffix}"
        for suffix in (
            "StateRaw",
            "StateCode",
            "StateValue",
            "LinkCode",
            "LinkValue",
            "State_RBV",
            "Link_RBV",
            "State_SP",
        )
    ]
    (package,) = ethercat.create_ethercat_packages([terminal], PV_MACROS)
    records = package.records
    assert [record.pvname for record in records] == expected_pvs
    records_by_suffix = {
        record.pvname.rsplit(":", maxsplit=1)[-1]: record for record in records
    }
    for suffix in ("State_RBV", "Link_RBV", "State_SP"):
        alias = f"$(PREFIX)ECAT:{terminal.pv_component}:{suffix}"
        assert records_by_suffix[suffix].aliases == [alias]
        assert f'alias("{alias}")' in database
    for pvname in expected_pvs:
        assert f'"{pvname}"' in database
    assert f'record(longin, "{base}:StateRaw")' in database
    assert f'record(calc, "{base}:StateCode")' in database
    assert f'record(calc, "{base}:StateValue")' in database
    assert all(
        record.fields["DESC"] == terminal.name
        for record in package.records
    )
    assert database.count(f'field(DESC, "{terminal.name}")') == len(expected_pvs)
    assert f'field(CALC, "{ethercat.DEVICE_STATE_ENUM_CALC_EXPRESSION}")' in database
    assert f'record(calc, "{base}:LinkValue")' in database
    assert "MULTIPLE_FLAGS" in database
    assert f'record(mbbi, "{base}:State_RBV")' in database
    assert 'field(ZRST, "INIT")' in database
    assert 'field(ONST, "PREOP")' in database
    assert 'field(TWST, "BOOTSTRAP")' in database
    assert 'field(THST, "SAFEOP")' in database
    assert 'field(FRST, "OP")' in database
    assert {
        field: records_by_suffix["State_RBV"].fields[field]
        for field in ("ZRSV", "ONSV", "TWSV", "THSV")
    } == {
        "ZRSV": "MAJOR",
        "ONSV": "MAJOR",
        "TWSV": "MAJOR",
        "THSV": "MAJOR",
    }
    assert records_by_suffix["State_RBV"].fields["FRSV"] == "NO_ALARM"
    assert records_by_suffix["State_RBV"].fields["UNSV"] == "MAJOR"
    assert f'record(mbbi, "{base}:Link_RBV")' in database
    assert records_by_suffix["Link_RBV"].fields["ZRSV"] == "NO_ALARM"
    assert all(
        records_by_suffix["Link_RBV"].fields[field] == "MAJOR"
        for field in (
            "ONSV",
            "TWSV",
            "THSV",
            "FRSV",
            "FVSV",
            "SXSV",
            "SVSV",
            "EISV",
            "NISV",
        )
    )
    assert 'field(DTYP, "Soft Channel")' in database
    assert f'record(mbbo, "{base}:State_SP")' in database
    assert (
        f"ADSPORT={ethercat.ADS_ETHERCAT_MASTER_AMS_PORT}/.ADR."
        f"16#{ethercat.ADS_ECAT_SLAVE_STATE_INDEX_GROUP:x},"
        f"16#{terminal.port:x},{ethercat.ADS_UINT16_SIZE_BYTES},"
        f"{ethercat.ADS_UINT16_DATA_TYPE}="
    ) in database
    key = f"{terminal.port}_{terminal.access_component}"
    assert f'field(DISP, "$(ECAT_DISP_{key}=1)")' in database
    assert f'field(DISA, "$(ECAT_DISA_{key}=1)")' in database
    assert f'field(ASG, "$(ECAT_ASG_{key}=NO_WRITE)")' in database
    assert 'field(DISV, "1")' in database
    assert 'field(ASG, "NO_WRITE")' in database
    assert 'field(SCAN, "$(ECAT_STATE_SCAN_SECONDS=2) second")' in database


def test_ethercat_terminal_alias_uses_sanitized_name():
    terminal = ethercat.EtherCATTerminal(port=1001, name="Device / A")
    (package,) = ethercat.create_ethercat_packages(
        [terminal], PV_MACROS
    )
    records_by_suffix = {
        record.pvname.rsplit(":", maxsplit=1)[-1]: record for record in package.records
    }

    assert terminal.pv_component == "Device___A"
    assert records_by_suffix["State_RBV"].pvname == (
        "$(PREFIX)ECAT:1001:State_RBV"
    )
    assert records_by_suffix["State_RBV"].aliases == [
        "$(PREFIX)ECAT:Device___A:State_RBV"
    ]


def test_ethercat_aliases_truncate_after_macro_expansion_and_remain_unique():
    terminals = [
        ethercat.EtherCATTerminal(1001, "T" * 80 + "A", "1"),
        ethercat.EtherCATTerminal(1002, "T" * 80 + "B", "2"),
    ]
    macros = {"PREFIX": "P" * 30}
    packages = ethercat.create_ethercat_packages(terminals, macros)
    aliases = [
        package.records[-3].aliases[0]
        for package in packages
    ]
    expanded_lengths = [
        get_record_pv_length(
            package.records[-3], macros, pvname=package.records[-3].aliases[0]
        )
        for package in packages
    ]

    assert len(set(aliases)) == len(aliases)
    assert expanded_lengths == [60, 60]
    assert all("_id" in alias for alias in aliases)


def test_ethercat_alias_collisions_fall_back_to_ads_port_for_duplicate_ids():
    terminals = [
        ethercat.EtherCATTerminal(1001, "Terminal " * 20, "7"),
        ethercat.EtherCATTerminal(1002, "Terminal " * 20, "7"),
    ]
    packages = ethercat.create_ethercat_packages(terminals, PV_MACROS)
    aliases = [package.records[-3].aliases[0] for package in packages]

    assert len(set(aliases)) == 2
    assert "_port-1001:" in aliases[0]
    assert "_port-1002:" in aliases[1]


def test_ethercat_alias_identifier_does_not_create_new_collision():
    terminals = [
        ethercat.EtherCATTerminal(1001, "T" * 80 + "A", "1"),
        ethercat.EtherCATTerminal(1002, "T" * 80 + "B", "2"),
        ethercat.EtherCATTerminal(1003, "T" * 32 + "_id-1", "3"),
    ]
    packages = ethercat.create_ethercat_packages(terminals, PV_MACROS)
    aliases = [package.records[-3].aliases[0] for package in packages]

    assert len(set(aliases)) == len(aliases)
    assert all(
        get_record_pv_length(record, PV_MACROS, pvname=record.aliases[0]) <= 60
        for package in packages
        for record in [package.records[-3]]
    )


def test_generate_ethercat_files_preserves_config(project, terminals, tmp_path):
    plc_database = tmp_path / "plc.db"
    database_path, config_path = ethercat.generate_ethercat_files(
        project, plc_database, PV_MACROS
    )

    assert database_path == tmp_path / "plc_EtherCAT.db"
    assert config_path == tmp_path / "plc_ethercat_state_access.cmd"
    assert database_path.exists()
    assert config_path.read_text().startswith("# EtherCAT state-request access")
    assert f"# Port {terminals[0].port}: {terminals[0].name}" in config_path.read_text()

    config_path.write_text("user configuration\n")
    ethercat.generate_ethercat_files(project, plc_database, PV_MACROS)
    assert config_path.read_text() == "user configuration\n"


def test_generate_records_requires_tmc_for_all_records(tmp_path, caplog):
    project = parser.parse(KFE_GMD_PROJECT)
    plc = list(project.plcs)[0]
    plc.tmc = None
    plc_database = tmp_path / f"{plc.name}.db"

    filenames, records = generate_records(
        plc,
        path=plc_database,
        write_archive_file=False,
        macro_substitutions=PV_MACROS,
    )

    assert filenames == []
    assert records == {}
    assert not plc_database.exists()
    assert not (tmp_path / f"{plc_database.stem}_EtherCAT.db").exists()
    assert not (tmp_path / f"{plc_database.stem}_ethercat_state_access.cmd").exists()
    assert "has no TMC file" not in caplog.text


