def test_effective_access_is_default_deny_and_requires_both_gates(terminals, tmp_path):
    terminal = terminals[0]
    config = tmp_path / "access.cmd"
    config.write_text(
        f'epicsEnvSet("ECAT_ASG_{terminal.port}_{terminal.access_component}", '
        '"DEFAULT")\n'
        f'epicsEnvSet("ECAT_DISP_{terminal.port}_{terminal.access_component}", "0")\n'
        f'epicsEnvSet("ECAT_DISA_{terminal.port}_{terminal.access_component}", "0")\n'
    )
    assignments = ethercat.read_access_config(config)
    decisions, unmatched = ethercat.effective_access(terminals, assignments)
    allowed = next(item for item in decisions if item.terminal == terminal)
    denied = next(item for item in decisions if item.terminal.port != terminal.port)

    assert allowed.caput_allowed
    assert allowed.internal_processing_allowed
    assert not denied.caput_allowed
    assert not denied.internal_processing_allowed
    assert not unmatched

    config.write_text(
        f'epicsEnvSet("ECAT_ASG_{terminal.port}_{terminal.access_component}", '
        '"DEFAULT")\n'
        f'epicsEnvSet("ECAT_DISP_{terminal.port}_{terminal.access_component}", "0")\n'
    )
    assignments = ethercat.read_access_config(config)
    decisions, _ = ethercat.effective_access(terminals, assignments)
    partial = next(item for item in decisions if item.terminal == terminal)
    assert partial.caput_allowed
    assert not partial.internal_processing_allowed


def test_access_report_and_unmatched_rules(terminals, tmp_path):
    terminal = terminals[0]
    config = tmp_path / "access.cmd"
    config.write_text(
        f'epicsEnvSet("ECAT_ASG_{terminal.port}_{terminal.access_component}", '
        '"DEFAULT")\n'
        f'epicsEnvSet("ECAT_DISP_{terminal.port}_{terminal.access_component}", "0")\n'
        f'epicsEnvSet("ECAT_DISA_{terminal.port}_{terminal.access_component}", "0")\n'
        'epicsEnvSet("ECAT_DISP_999_UNKNOWN", "0")\n'
    )
    output = io.StringIO()
    ethercat.print_access_report(terminals, config, output)

    assert "CAPUT" in output.getvalue()
    assert "ALLOWED" in output.getvalue()
    assert "Unmatched access rule: port=999 device=UNKNOWN" in output.getvalue()


