def test_access_config_detects_renamed_device_with_same_access_component(tmp_path):
    old = ethercat.EtherCATTerminal(port=1001, name="DEVICE-A")
    new = ethercat.EtherCATTerminal(port=1001, name="DEVICE_A")
    config = tmp_path / "access.cmd"
    config.write_text(ethercat.render_default_access_config([old]), encoding="utf-8")

    added, removed = ethercat.access_config_device_changes([new], config)

    assert added == [new]
    assert removed == [old]


