def test_ethercat_access_cli_patch(project_path, terminals, tmp_path, capsys, monkeypatch):
    retained = terminals[-1]
    removed = ethercat.EtherCATTerminal(port=9999, name="REMOVED_DEVICE")
    config = tmp_path / "access.cmd"
    config.write_text(
        ethercat.render_default_access_config([removed, retained]),
        encoding="utf-8",
    )
    asg_line = (
        f'# epicsEnvSet("ECAT_ASG_{retained.port}_{retained.access_component}", '
        '"DEFAULT")'
    )
    config.write_text(
        config.read_text(encoding="utf-8").replace(asg_line, asg_line[2:]),
        encoding="utf-8",
    )
    monkeypatch.setattr(
        "builtins.input",
        lambda prompt: (print(prompt), "y")[1],
    )

    ethercat_access_main(str(project_path), str(config), patch=True)

    output = capsys.readouterr().out
    assert "Remove port=9999 device=REMOVED_DEVICE" in output
    assert "Apply these changes? [y/N]" in output
    assert output.index("Remove port=9999") < output.index("Apply these changes?")
    assert "Updated access file:" in output
    for terminal in terminals:
        if terminal != retained:
            assert f"Add port={terminal.port} device={terminal.name}" in output

    updated = config.read_text(encoding="utf-8")
    sections = [
        line for line in updated.splitlines() if line.startswith("# Port ")
    ]
    expected = sorted(terminals)
    assert sections == [
        f"# Port {terminal.port}: {terminal.name}" for terminal in expected
    ]
    assert (
        f'epicsEnvSet("ECAT_ASG_{retained.port}_{retained.access_component}", '
        '"DEFAULT")'
    ) in updated
    assert "REMOVED_DEVICE" not in updated
    for terminal in terminals:
        if terminal == retained:
            continue
        assert (
            f'# epicsEnvSet("ECAT_ASG_{terminal.port}_{terminal.access_component}", '
            '"DEFAULT")'
        ) in updated


