def test_template_rejects_nonpositive_scan_period():
    from pytmc.bin.template import main as template_main

    with pytest.raises(ValueError, match="positive number of seconds"):
        template_main(
            [str(KFE_GMD_PROJECT)],
            macros=["ethercat_state_scan_seconds=0"],
        )
